INSERT INTO `testcase_generation_task` VALUES (1,'gen_e782dbfcd060','鐢ㄦ埛鐧诲綍鍔熻兘','闇€姹傛爣棰? 鐢ㄦ埛鐧诲綍鍔熻兘\n\n闇€姹傛弿杩?\n鐢ㄦ埛鐧诲綍鍔熻兘','completed',100,'stream','\n\n```json\n[\n  {\n    \"case_id\": \"LOGIN_001\",\n    \"title\": \"姝ｅ父鐧诲綍-浣跨敤姝ｇ‘鐨勭敤鎴峰悕鍜屽瘑鐮乗",\n    \"priority\": \"P0\",\n    \"precondition\": \"鐢ㄦ埛宸叉敞鍐岋紝璐﹀彿鐘舵€佹甯竆",\n    \"test_steps\": \"1. 鎵撳紑鐧诲綍椤甸潰\\n2. 杈撳叆姝ｇ‘鐨勭敤鎴峰悕\\n3. 杈撳叆姝ｇ‘鐨勫瘑鐮乗\n4. 鐐瑰嚮鐧诲綍鎸夐挳\",\n    \"expected_result\": \"鐧诲綍鎴愬姛锛岃烦杞埌棣栭〉鎴栫敤鎴蜂腑蹇冿紝鏄剧ず鐢ㄦ埛淇℃伅\"\n  },\n  {\n    \"case_id\": \"LOGIN_002\",\n    \"title\": \"姝ｅ父鐧诲綍-浣跨敤璁颁綇瀵嗙爜鍔熻兘\",\n    \"priority\": \"P1\",\n    \"precondition\": \"鐢ㄦ埛棣栨鐧诲綍锛屽嬀閫変簡璁颁綇瀵嗙爜\",\n    \"test_steps\": \"1. 鎵撳紑鐧诲綍椤甸潰\\n2. 杈撳叆姝ｇ‘鐨勭敤鎴峰悕鍜屽瘑鐮乗\n3. 鍕鹃€夆€滆浣忓瘑鐮佲€濆閫夋\\n4. 鐐瑰嚮鐧诲綍鎸夐挳\\n5. 閫€鍑虹郴缁焅\n6. 閲嶆柊鎵撳紑鐧诲綍椤甸潰\",\n    \"expected_result\": \"鐢ㄦ埛鍚嶅拰瀵嗙爜瀛楁鑷姩濉厖涓婃鐧诲綍淇℃伅\"\n  },\n  {\n    \"case_id\": \"LOGIN_003\",\n    \"title\": \"寮傚父鐧诲綍-鐢ㄦ埛鍚嶄笉瀛樺湪\",\n    \"priority\": \"P0\",\n    \"precondition\": \"绯荤粺涓笉瀛樺湪璇ョ敤鎴峰悕\",\n    \"test_steps\": \"1. 鎵撳紑鐧诲綍椤甸潰\\n2. 杈撳叆涓嶅瓨鍦ㄧ殑鐢ㄦ埛鍚峔\n3. 杈撳叆浠绘剰瀵嗙爜\\n4. 鐐瑰嚮鐧诲綍鎸夐挳\",\n    \"expected_result\": \"鎻愮ず鈥滅敤鎴峰悕涓嶅瓨鍦ㄢ€濇垨鈥滆处鍙锋湭娉ㄥ唽鈥濓紝涓嶆毚闇插叿浣撻敊璇師鍥燶"\n  },\n  {\n    \"case_id\": \"LOGIN_004\",\n    \"title\": \"寮傚父鐧诲綍-瀵嗙爜閿欒\",\n    \"priority\": \"P0\",\n    \"precondition\": \"鐢ㄦ埛宸叉敞鍐岋紝璐﹀彿鐘舵€佹甯竆",\n    \"test_steps\": \"1. 鎵撳紑鐧诲綍椤甸潰\\n2. 杈撳叆姝ｇ‘鐨勭敤鎴峰悕\\n3. 杈撳叆閿欒鐨勫瘑鐮乗\n4. 鐐瑰嚮鐧诲綍鎸夐挳\",\n    \"expected_result\": \"鎻愮ず鈥滅敤鎴峰悕鎴栧瘑鐮侀敊璇€濓紝涓嶆槑纭寚鍑烘槸瀵嗙爜闂\"\n  },\n  {\n    \"case_id\": \"LOGIN_005\",\n    \"title\": \"寮傚父鐧诲綍-鐢ㄦ埛鍚嶄负绌篭",\n    \"priority\": \"P0\",\n    \"precondition\": \"鐧诲綍椤甸潰姝ｅ父鍔犺浇\",\n    \"test_steps\": \"1. 鎵撳紑鐧诲綍椤甸潰\\n2. 鐢ㄦ埛鍚嶈緭鍏ユ鐣欑┖\\n3. 杈撳叆浠绘剰瀵嗙爜\\n4. 鐐瑰嚮鐧诲綍鎸夐挳\",\n    \"expected_result\": \"鎻愮ず鈥滅敤鎴峰悕涓嶈兘涓虹┖鈥濇垨鈥滆杈撳叆鐢ㄦ埛鍚嶁€濓紝杈撳叆妗嗛珮浜樉绀篭"\n  },\n  {\n    \"case_id\": \"LOGIN_006\",\n    \"title\": \"寮傚父鐧诲綍-瀵嗙爜涓虹┖\",\n    \"priority\": \"P0\",\n    \"precondition\": \"鐧诲綍椤甸潰姝ｅ父鍔犺浇\",\n    \"test_steps\": \"1. 鎵撳紑鐧诲綍椤甸潰\\n2. 杈撳叆鐢ㄦ埛鍚峔\n3. 瀵嗙爜杈撳叆妗嗙暀绌篭\n4. 鐐瑰嚮鐧诲綍鎸夐挳\",\n    \"expected_res